import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sourceRoot = path.join(repoRoot, "web", "src");
const distRoot = path.join(repoRoot, "web", "dist");

const entries = [
  {
    entry: path.join(sourceRoot, "pages", "home.js"),
    output: path.join(distRoot, "home.bundle.js")
  },
  {
    entry: path.join(sourceRoot, "pages", "detail.js"),
    output: path.join(distRoot, "detail.bundle.js")
  }
];

const importPattern = /^import\s+\{([^}]+)\}\s+from\s+["']([^"']+)["'];\s*$/gm;
const exportConstPattern = /export const ([A-Za-z0-9_$]+)\s*=/g;
const exportFunctionPattern = /export function ([A-Za-z0-9_$]+)\s*\(/g;
const exportListPattern = /export\s*\{([^}]+)\};?\s*$/gm;

function toModuleId(absolutePath) {
  return `src/${path.relative(sourceRoot, absolutePath).split(path.sep).join("/")}`;
}

function indent(text, spaces) {
  const prefix = " ".repeat(spaces);
  return text
    .split("\n")
    .map((line) => `${prefix}${line}`)
    .join("\n");
}

function parseNamedImports(specifierList) {
  return specifierList
    .split(",")
    .map((part) => part.trim())
    .filter(Boolean)
    .map((part) => {
      const [imported, local] = part.split(/\s+as\s+/);
      return local ? `${imported.trim()}: ${local.trim()}` : imported.trim();
    })
    .join(", ");
}

function parseExportList(specifierList) {
  return specifierList
    .split(",")
    .map((part) => part.trim())
    .filter(Boolean)
    .map((part) => {
      const [local, exported] = part.split(/\s+as\s+/);
      return {
        local: local.trim(),
        exported: (exported ?? local).trim()
      };
    });
}

function resolveImport(fromPath, specifier) {
  const resolved = path.resolve(path.dirname(fromPath), specifier);

  if (!resolved.startsWith(sourceRoot)) {
    throw new Error(`Unsupported import outside web/src: ${specifier} from ${fromPath}`);
  }

  return resolved;
}

async function collectModule(absolutePath, modules) {
  const moduleId = toModuleId(absolutePath);
  if (modules.has(moduleId)) {
    return;
  }

  const source = await fs.readFile(absolutePath, "utf8");
  const dependencies = [];
  const exports = [];

  let transformed = source.replace(importPattern, (_, names, specifier) => {
    const dependencyPath = resolveImport(absolutePath, specifier);
    const dependencyId = toModuleId(dependencyPath);
    dependencies.push(dependencyPath);
    return `const { ${parseNamedImports(names)} } = requireModule("${dependencyId}");`;
  });

  transformed = transformed.replace(exportConstPattern, (_, exportName) => {
    exports.push({ local: exportName, exported: exportName });
    return `const ${exportName} =`;
  });

  transformed = transformed.replace(exportFunctionPattern, (_, exportName) => {
    exports.push({ local: exportName, exported: exportName });
    return `function ${exportName}(`;
  });

  transformed = transformed.replace(exportListPattern, (_, exportList) => {
    exports.push(...parseExportList(exportList));
    return "";
  });

  const dedupedExports = Array.from(
    new Map(exports.map((entry) => [entry.exported, entry])).values()
  );

  modules.set(moduleId, {
    id: moduleId,
    path: absolutePath,
    code: transformed.trimEnd(),
    exports: dedupedExports
  });

  for (const dependencyPath of dependencies) {
    await collectModule(dependencyPath, modules);
  }
}

function buildFactorySource(moduleRecord) {
  const exportBlock =
    moduleRecord.exports.length === 0
      ? "return {};"
      : `return {\n${moduleRecord.exports
          .map(({ local, exported }) => `  ${JSON.stringify(exported)}: ${local}`)
          .join(",\n")}\n};`;

  return `  ${JSON.stringify(moduleRecord.id)}: function(requireModule) {\n${indent(
    `${moduleRecord.code}\n\n${exportBlock}`,
    4
  )}\n  }`;
}

async function buildBundle({ entry, output }) {
  const modules = new Map();
  await collectModule(entry, modules);

  const bundleSource = `// Generated by scripts/build-web-bundle.mjs. Edit files in web/src and rebuild.
(() => {
  const moduleFactories = {
${Array.from(modules.values())
  .sort((left, right) => left.id.localeCompare(right.id))
  .map((moduleRecord) => buildFactorySource(moduleRecord))
  .join(",\n")}
  };

  const moduleCache = {};

  function requireModule(moduleId) {
    if (moduleCache[moduleId]) {
      return moduleCache[moduleId];
    }

    const factory = moduleFactories[moduleId];
    if (!factory) {
      throw new Error(\`Unknown module: \${moduleId}\`);
    }

    const exports = factory(requireModule);
    moduleCache[moduleId] = exports;
    return exports;
  }

  requireModule(${JSON.stringify(toModuleId(entry))});
})();
`;

  await fs.mkdir(path.dirname(output), { recursive: true });
  await fs.writeFile(output, bundleSource);
}

for (const entryConfig of entries) {
  await buildBundle(entryConfig);
}

console.log("build-web-bundle: ok");
